from typing import List

def can_reorder(a: List[int]) -> bool:
    return len(set(a[:len(a)//2])) != len(set(a[len(a)//2:]))

def reorder_array(a: List[int]) -> List[int]:
    if not can_reorder(a):
        return [-1]

    first_half = sorted(a[:len(a)//2], reverse=True)
    second_half = sorted(a[len(a)//2:], reverse=True)

    result = []
    i, j = 0, 0

    while i < len(first_half) or j < len(second_half):
        if i < len(first_half):
            result.append(first_half[i])
            i += 1
        if j < len(second_half):
            result.append(second_half[j])
            j += 1

    return result

