import sys

def can_reorder(a: List[int], n: int) -> bool:
    return sum(a[:n]) != sum(a[n:])

def find_reordering(a: List[int], n: int) -> List[int]:
    if can_reorder(a, n):
        return a
    else:
        return [-1]

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = find_reordering(a, n)
    if result == [-1]:
        print(-1)
    else:
        print(' '.join(map(str, result)))

